def merge(items):
    out = []
    for s, e, cs, ce in sorted(items):
        if out and s <= out[-1][1]:
            out[-1] = (out[-1][0], max(out[-1][1], e), out[-1][2], ce)
        else:
            out.append((s, e, cs, ce))
    return out

