import db

def create(name, email):
    if find_by_email(email):
        raise ValueError('email taken')
    return db.insert({'name': name, 'email': email.lower()})

def get(uid):
    return db.ROWS[uid]

def find_by_email(email):
    for r in db.ROWS.values():
        if r['email'] == email.lower():
            return r
    return None

def list_users():
    return sorted(db.ROWS.values(), key=lambda r: r['id'])

def count():
    return len(db.ROWS)

def delete(uid):
    db.remove(uid)

