import users

def handle(method, path, body=None):
    parts = path.strip('/').split('/')
    try:
        if method == 'GET' and parts == ['users']:
            return 200, [u['name'] for u in users.list_users()]
        if method == 'GET' and len(parts) == 2:
            return 200, users.get(int(parts[1]))['name']
        if method == 'DELETE' and len(parts) == 2:
            users.delete(int(parts[1])); return 204, None
        if method == 'POST' and parts == ['users']:
            return 201, users.create(body['name'], body['email'])
    except KeyError:
        return 404, None
    except ValueError as e:
        return 409, str(e)
    return 400, None

