import csv, io

def export_customers(customers):
    buf = io.StringIO()
    w = csv.writer(buf, delimiter=';', lineterminator='\n')
    w.writerow(['customer_name', 'created_on'])
    for c in customers:
        w.writerow([c['name'], c['created'].isoformat()])
    return buf.getvalue()

